import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  group.position.set(0, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const toDispose = [];

  // Background image plane
  const bgTexture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/orb-decor.png');
  bgTexture.colorSpace = THREE.SRGBColorSpace;
  toDispose.push(bgTexture);

  // Geometry: 512x320 aspect ratio (1.6:1)
  const bgGeometry = new THREE.PlaneGeometry(1.6, 1);
  toDispose.push(bgGeometry);

  const bgMaterial = new MeshBasicNodeMaterial({
    map: bgTexture,
    transparent: true,
  });
  toDispose.push(bgMaterial);

  const bgMesh = new THREE.Mesh(bgGeometry, bgMaterial);
  group.add(bgMesh);

  // Text via fontAtlas
  if (config.textContent && config.textContent.length > 0) {
    const textConfig = config.textContent[0];
    const textMesh = ctx.fontAtlas.createTextMesh({
      text: textConfig.text || 'Features 2',
      fontSize: 0.34,
      fontFamily: 'Lora',
      fontWeight: 400,
      color: 0x16161d,
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Cleanup
  group.userData.cleanup = () => {
    toDispose.forEach(item => item.dispose?.());
  };

  group.userData.handlers = {};

  return group;
}
